solution.Solution.cs:
using System.Globalization;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.Json.Serialization;

public enum Priority { Low, Normal, High }
public record TodoItem(int Id, string Title, Priority Priority, bool Done, DateOnly? Due);

public static class TodoJson
{
    private static readonly JsonSerializerOptions Options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
        Converters = { new JsonStringEnumConverter(JsonNamingPolicy.CamelCase) },
    };

    public static string Save(IEnumerable<TodoItem> items) => JsonSerializer.Serialize(items.ToList(), Options);

    public static List<TodoItem> Load(string json)
    {
        if (string.IsNullOrWhiteSpace(json)) return new();
        try
        {
            var items = JsonSerializer.Deserialize<List<TodoItem>>(json, Options) ?? new();
            return items.Where(i => i is not null && !string.IsNullOrWhiteSpace(i.Title)).ToList();
        }
        catch (JsonException)
        {
            return new();
        }
    }

    public static List<string> OverdueTitles(string json, DateOnly today)
    {
        var result = new List<string>();
        if (JsonNode.Parse(json) is not JsonArray array) return result;
        foreach (var node in array)
        {
            if (node is null) continue;
            bool done = node["done"]?.GetValue<bool>() ?? false;
            string? due = node["due"]?.GetValue<string>();
            if (done || due is null) continue;
            if (DateOnly.ParseExact(due, "yyyy-MM-dd", CultureInfo.InvariantCulture) < today)
                result.Add(node["title"]?.GetValue<string>() ?? "");
        }
        return result;
    }
}

unitTests:
var items = new List<TodoItem>
{
    new(1, "Tea", Priority.High, false, new DateOnly(2026, 3, 1)),
    new(2, "Cake", Priority.Low, true, new DateOnly(2026, 2, 1)),
    new(3, "Mug", Priority.Normal, false, null),
    new(4, "Pen", Priority.Normal, false, new DateOnly(2026, 4, 1)),
};

Test("saving", () =>
{
    string json = TodoJson.Save(items.Take(1));
    CheckEq(json, "[{\"id\":1,\"title\":\"Tea\",\"priority\":\"high\",\"done\":false,\"due\":\"2026-03-01\"}]");
    Check(!TodoJson.Save(items).Contains("\"due\":null"), "null due dates should be left out");
    Check(!TodoJson.Save(items).Contains('\n'), "not indented");
});

Test("loading round-trips", () =>
{
    var back = TodoJson.Load(TodoJson.Save(items));
    CheckEq(back.Count, 4);
    CheckEq(back[0], items[0]);
    CheckEq(back[2].Due, null);
    CheckEq(back[3].Priority, Priority.Normal);
});

Test("loading bad input", () =>
{
    CheckEq(TodoJson.Load("").Count, 0);
    CheckEq(TodoJson.Load("null").Count, 0);
    CheckEq(TodoJson.Load("[{ oops").Count, 0);
    CheckEq(TodoJson.Load("[{\"id\":1,\"title\":\" \",\"priority\":\"low\",\"done\":false},{\"id\":2,\"priority\":\"low\",\"done\":true},{\"id\":3,\"title\":\"ok\",\"priority\":\"low\",\"done\":true}]")
        .Select(i => i.Id), new[] { 3 });
});

Test("overdue with JsonNode", () =>
{
    string json = TodoJson.Save(items);
    CheckEq(TodoJson.OverdueTitles(json, new DateOnly(2026, 3, 15)), new[] { "Tea" });
    CheckEq(TodoJson.OverdueTitles(json, new DateOnly(2026, 5, 1)), new[] { "Tea", "Pen" });
    CheckEq(TodoJson.OverdueTitles("[]", new DateOnly(2026, 1, 1)).Count, 0);
});

